import yaml, json
path = '/home/ubuntu/.agent-ml-research-idea_gen_0509_14/projects/distill_sparse_swiglu/registry.yaml'
with open(path) as f:
    data = yaml.safe_load(f)

# Table 2 relevant experiments: KL/BCE/MSE/TEAL at various sparsities, multi-seed
# Group by method + sparsity + allocation
groups = {}
for exp_id, exp in data.get('experiments', {}).items():
    m = exp.get('metrics', {})
    ppl = m.get('wikitext2_ppl') or m.get('ppl_wikitext2') or m.get('predictor_hard_mask_ppl')
    if not ppl:
        continue
    # identify seed
    seed = None
    spec = exp.get('spec', {})
    if isinstance(spec, dict):
        seed = spec.get('seed')
    # Try to identify from exp_id
    for s in ['s42', 's123', 's456']:
        if s in exp_id:
            seed = int(s[1:])
            break

    # Try to categorize
    eid = exp_id.lower()
    conclusion = exp.get('conclusion', '')
    status = exp.get('status', '')

    # Skip failed/killed
    if conclusion in ['failed', 'killed']:
        continue

    info = f'{exp_id}: PPL={ppl}, seed={seed}, status={status}, conclusion={conclusion}'

    # Categorize into Table 2 rows
    if 'kl' in eid and '50' in eid and 'global' in eid and 'eval' in eid:
        groups.setdefault('KL 50% global', []).append(info)
    elif 'kl' in eid and '50' in eid and ('uniform' in eid or 'd030' not in eid):
        groups.setdefault('KL 50% (other)', []).append(info)
    elif 'kl' in eid and '30' in eid:
        groups.setdefault('KL 30%', []).append(info)
    elif 'kl' in eid and '40' in eid:
        groups.setdefault('KL 40%', []).append(info)
    elif 'kl' in eid and '70' in eid:
        groups.setdefault('KL 70%', []).append(info)
    elif 'bce' in eid and '50' in eid:
        groups.setdefault('BCE 50%', []).append(info)
    elif 'mse' in eid and '50' in eid:
        groups.setdefault('MSE 50%', []).append(info)
    elif 'mse' in eid and '30' in eid:
        groups.setdefault('MSE 30%', []).append(info)
    elif 'teal' in eid:
        groups.setdefault('TEAL baseline', []).append(info)
    elif 'mvp_kl' in eid:
        groups.setdefault('KL 50% (mvp)', []).append(info)

for group, entries in sorted(groups.items()):
    print(f'\\n### {group}')
    for e in entries:
        print(f'  {e}')
"

